      energy: Math.max(0, Math.min(cap, Number.isFinite(storedEnergy) ? storedEnergy : cap)), energyMax: cap, energyAt: store.energy.at, regenMinutes: eregen() / 60000,
      infiniteEnergyUntil: Number.isFinite(store.infiniteEnergyUntil) ? store.infiniteEnergyUntil : 0,
      premium: isPlus(), freezes: store.freezes || 0, examDate: store.settings.examDate || null, name: store.settings.name || null,
      nextTitle: (rec && rec.title) || null, nextSub: (rec && rec.sub) || null, nextPath: rec && rec.href ? rec.href.replace(/^#/, "") : "/",
      words: LZ.wordsFrom ? LZ.wordsFrom(new Date(), 14) : [], wordsDay: dayKey(),
