  /* ---------- feedback: sound, haptics, toast, confetti ---------- */
  let actx = null;
  /* Soft bell-like tones: a sine with a quiet octave on top, a gentle attack and a long fade, all well
     under the phone's other sounds. Only moments that matter make a sound (right, wrong, done, streak);
     taps and navigation are felt, not heard – beeping on every tap was the owner's biggest annoyance. */
  function tone(notes, vol) {
    if (!store.sound || document.hidden) return;
    try {
      actx = actx || new (window.AudioContext || window.webkitAudioContext)();
      if (actx.state === "suspended") actx.resume();
      const t0 = actx.currentTime + 0.01, peak = vol || 0.06;
      notes.forEach(([f, at, dur]) => [[f, peak], [f * 2, peak * 0.18]].forEach(([freq, v]) => {
        const o = actx.createOscillator(), g = actx.createGain();
        o.type = "sine"; o.frequency.value = freq;
        g.gain.setValueAtTime(0.0001, t0 + at);
        g.gain.exponentialRampToValueAtTime(v, t0 + at + 0.02);
        g.gain.exponentialRampToValueAtTime(0.0001, t0 + at + dur);
        o.connect(g).connect(actx.destination); o.start(t0 + at); o.stop(t0 + at + dur + 0.05);
      }));
    } catch (e) {}
  }
