    let startY = null;
    panel.addEventListener("touchstart", (e) => { if (panel.scrollTop <= 0) startY = e.touches[0].clientY; }, { passive: true });
    panel.addEventListener("touchmove", (e) => { if (startY == null) return; const dy = e.touches[0].clientY - startY; if (dy > 0) panel.style.transform = "translateY(" + dy + "px)"; }, { passive: true });
    panel.addEventListener("touchend", (e) => { if (startY == null) return; const dy = e.changedTouches[0].clientY - startY; startY = null; panel.style.transform = ""; if (dy > 110) close(); });
