      release: "lozenge@" + (window.LZNative ? window.LZNative.version : "web"), environment: window.LZNative && window.LZNative.debug ? "development" : "production",
      tags: { kind, app: plat.split(" ")[0], route: String(route).replace(/\/[0-9a-f-]{8,}/gi, "/:id").slice(0, 80), lang: (LZ.store && (LZ.store().lang || "")) || "" },
