/* ---- textsize.js ---- */
;/* Lozenge – text size. Every size in the stylesheet is in rem, and the root font size is
   16px × --ts. On iPhone --ts follows the reader's own Dynamic Type setting (Settings ›
   Display & Brightness › Text Size), which we read by measuring a probe styled with the
   system body font. Settings › Text size can override that. */
(function () {
  const BODY_AT_DEFAULT = 17;   // -apple-system-body at the standard iOS text size
  const MIN = 0.85, MAX = 1.6;  // beyond this the layout stops being usable on a phone

  /* How much bigger than standard the reader's system text is, 1 when we can't tell. */
  function systemScale() {
    try {
      const probe = document.createElement("span");
      probe.setAttribute("aria-hidden", "true");
      probe.style.cssText = "position:absolute;visibility:hidden;font:-apple-system-body";
      document.body.append(probe);
      const size = parseFloat(getComputedStyle(probe).fontSize);
      probe.remove();
      if (!size || !isFinite(size)) return 1;
      return size / BODY_AT_DEFAULT;
    } catch (e) { return 1; }
  }

  LZ.applyTextSize = () => {
    const chosen = (LZ.store().settings || {}).textScale;
    const scale = !chosen || chosen === "auto" ? systemScale() : parseFloat(chosen) || 1;
    const clamped = Math.min(MAX, Math.max(MIN, scale));
    document.documentElement.style.setProperty("--ts", clamped.toFixed(3));
    /* Past this point the top bar has to give up its labels to keep the numbers readable. */
    document.documentElement.classList.toggle("big-text", clamped >= 1.35);
    /* A little larger than standard: the word "lozenge" beside the mark would run into the counters. */
    document.documentElement.classList.toggle("mid-text", clamped >= 1.1);
  };

  LZ.applyTextSize();
  /* iOS reports a new Dynamic Type size on the way back into the app. */
  window.addEventListener("pageshow", () => LZ.applyTextSize());
  document.addEventListener("visibilitychange", () => { if (!document.hidden) LZ.applyTextSize(); });
})();


/* ---- recordings.js ---- */
;/* Lozenge – your Speaking answers, kept on the device. A recording used to live only in memory,
   so leaving the screen threw it away; now each answer is stored in IndexedDB and comes back the
   next time you open that Speaking test. Nothing is ever uploaded.
   Each recording belongs to the account that made it (or "local" without one): another person logged in on the
   same phone never hears it, and deleting an account deletes its recordings. Recordings from before owners
   existed go to whoever uses the phone first after the update. */
(function () {
  const DB = "lozenge-recordings", STORE = "clips", VERSION = 1;
  const KEEP_TESTS = 3;            // recordings from the three most recent tests are kept
  let open = null, migrated = null;
  const owner = () => (LZ.account && LZ.account.user && LZ.account.user.id) || "local";

  function db() {
    if (open) return open;
    open = new Promise((resolve, reject) => {
      if (!("indexedDB" in window)) { reject(new Error("no IndexedDB")); return; }
      const req = indexedDB.open(DB, VERSION);
      req.onupgradeneeded = () => {
        const store = req.result.createObjectStore(STORE, { keyPath: "id", autoIncrement: true });
        store.createIndex("test", "test");
        store.createIndex("at", "at");
      };
      req.onsuccess = () => resolve(req.result);
      req.onerror = () => reject(req.error);
    });
    open.catch(() => { open = null; });
    return open;
  }

  const run = (mode, fn) => db().then((d) => new Promise((resolve, reject) => {
    const tx = d.transaction(STORE, mode), store = tx.objectStore(STORE);
    let out;
    try { out = fn(store); } catch (e) { reject(e); return; }
    tx.oncomplete = () => resolve(out && out.result !== undefined ? out.result : out);
    tx.onerror = () => reject(tx.error);
  }));

  /* rows saved before owners existed: given to the current owner, once */
  const migrate = () => migrated || (migrated = run("readwrite", (store) => {
    const req = store.getAll(), who = owner();
    req.onsuccess = () => (req.result || []).forEach((r) => { if (!r.owner) { r.owner = who; store.put(r); } });
  }).catch(() => {}));
  const mine = (rows) => (rows || []).filter((r) => (r.owner || owner()) === owner());

  LZ.recordings = {
    /* Save one answer. Failures are silent: a lost recording must never break the test. */
    save(test, label, blob) {
      return migrate().then(() => run("readwrite", (store) => store.add({ test, label, blob, at: Date.now(), owner: owner() })))
        .then(() => LZ.recordings.tidy())
        .catch(() => {});
    },

    /* Every answer kept for one test, oldest first, as { label, url }. */
    list(test) {
      return migrate().then(() => run("readonly", (store) => store.index("test").getAll(test)))
        .then((rows) => mine(rows).sort((a, b) => a.at - b.at).map((r) => ({ id: r.id, label: r.label, at: r.at, url: URL.createObjectURL(r.blob) })))
        .catch(() => []);
    },

    /* The audio itself, for the on-device transcriber. Kept separate from list() so the
       assessment screen doesn't hold every answer in memory just to draw a player. */
    blobFor(id) {
      return run("readonly", (store) => store.get(id))
        .then((row) => (row && (row.owner || owner()) === owner() && row.blob) || null)
        .catch(() => null);
    },

    /* For Settings: how much of the phone the recordings are using. */
    stats() {
      return migrate().then(() => run("readonly", (store) => store.getAll()))
        .then((rows) => {
          const list = mine(rows);
          return { clips: list.length, tests: new Set(list.map((r) => r.test)).size,
            bytes: list.reduce((a, r) => a + ((r.blob && r.blob.size) || 0), 0) };
        })
        .catch(() => ({ clips: 0, tests: 0, bytes: 0 }));
    },

    /* Settings › Speaking recordings: this account's (or "local") recordings */
    clearAll() { return LZ.recordings.clearOwner(owner()); },

    /* every recording of one account – when the account is deleted */
    clearOwner(who) {
      return run("readwrite", (store) => {
        const req = store.getAll();
        req.onsuccess = () => (req.result || []).forEach((r) => { if ((r.owner || who) === who) store.delete(r.id); });
      }).catch(() => {});
    },

    clear(test) {
      return run("readwrite", (store) => {
        const req = store.index("test").getAll(test);
        req.onsuccess = () => mine(req.result).forEach((r) => store.delete(r.id));
      }).catch(() => {});
    },

    /* Audio adds up, so only the newest few tests are kept. */
    tidy() {
      return run("readwrite", (store) => {
        const req = store.getAll();
        req.onsuccess = () => {
          const rows = mine(req.result);
          const tests = [...new Set(rows.sort((a, b) => b.at - a.at).map((r) => r.test))];
          const drop = new Set(tests.slice(KEEP_TESTS));
          rows.forEach((r) => { if (drop.has(r.test)) store.delete(r.id); });
        };
      }).catch(() => {});
    }
  };
})();


