        { t: "mc", s: "I think you've ___ the right decision.", o: ["done", "made", "had", "got"], a: 1, x: "make a decision." },
        { t: "match", pairs: [["make", "a mistake"], ["do", "your homework"], ["take", "a photo"], ["have", "a shower"]], x: "Four common collocations." },
        { t: "mc", s: "We need to ___ some research before we start.", o: ["do", "make", "take", "have"], a: 0, x: "do research." },
        { t: "mc", s: "Don't ___ any notice of what he says.", o: ["make", "do", "take", "give"], a: 2, x: "take (no) notice of something = pay (no) attention to it." },
        { t: "mc", s: "It doesn't ___ any difference to me.", o: ["have", "make", "do", "take"], a: 1, x: "make a difference." },
        { t: "type", s: "Have you ___ your bed this morning?", a: ["made"], hint: "make, do, take or have?", x: "make the bed." },
        { t: "mc", s: "Let's ___ a break – we've been working for hours.", o: ["give", "do", "have", "make"], a: 2, x: "have (or take) a break." }
