        { t: "type", s: "This is by ___ the best pizza in town.", a: ["far"], hint: "One word", x: "by far + superlative." },
        { t: "spot", s: "She is the more intelligent student in the class.", wrong: 3, fix: "most", x: "Superlative: the most intelligent." },
        { t: "mc", s: "There were ___ people at the party than we expected.", o: ["less", "least", "fewer", "little"], a: 2, x: "fewer + countable nouns." },
        { t: "tiles", s1: "The hotel was cheaper than we expected.", key: "AS", pre: "The hotel wasn't", post: "we expected.", tiles: ["as", "expensive", "as", "cheap", "than"], a: ["as", "expensive", "as"], x: "not as expensive as = cheaper than." },
        { t: "mc", s: "My sister is ___ person I know.", o: ["the most kind", "kinder", "the more kind", "the kindest"], a: 3, x: "kind → the kindest." },
        { t: "kwt", s1: "This is the hardest exam I've ever taken.", key: "HARDER", pre: "I've never taken", post: "this one.", a: [["a harder"], ["exam than"]], x: "never … a harder … than = the hardest." },
        { t: "mc", s: "The film was ___ interesting than the book.", o: ["fewer", "least", "lower", "less"], a: 3, x: "less + adjective + than." }
