  { id: "u22", title: "Contrast & purpose", part: "Part 4", color: "pink", icon: "pen",
    tips: ["although / even though + clause. despite / in spite of + noun or -ing.", "However starts a new sentence and is followed by a comma.", "Purpose: to / in order to / so as to + verb. so that + clause, often with can or could."],
    lessons: [
      { id: "u22l1", title: "although, despite, however", items: [
        { t: "mc", s: "___ it was raining, we went for a walk.", o: ["Despite", "Although", "However", "In spite"], a: 1, x: "although + clause." },
        { t: "mc", s: "We went out ___ the rain.", o: ["although", "even though", "despite", "however"], a: 2, x: "despite + noun." },
        { t: "spot", s: "Despite of the cold, we went swimming.", wrong: 1, fix: "(no ‘of’)", x: "despite – never despite of. (in spite of is correct.)" },
        { t: "type", s: "In spite ___ the noise, I slept well.", a: ["of"], hint: "One word", x: "in spite of + noun." },
        { t: "kwt", s1: "Although she is rich, she isn't happy.", key: "DESPITE", pre: "She isn't happy", post: "rich.", a: [["despite"], ["being"]], x: "despite + -ing: despite being rich." },
        { t: "tiles", pre: "The film was very long.", post: "it was worth watching.", tiles: ["However,", "Although", "Despite"], a: ["However,"], x: "However starts a new sentence and takes a comma." },
        { t: "match", pairs: [["although", "+ clause"], ["despite", "+ noun or -ing"], ["however", "starts a new sentence"], ["whereas", "compares two facts"]], x: "How each linker is used." },
        { t: "mc", s: "My brother loves football, ___ I prefer tennis.", o: ["whereas", "despite", "however", "in spite of"], a: 0, x: "whereas compares two different facts." }
      ] },
      { id: "u22l2", title: "Saying why: purpose", items: [
        { t: "mc", s: "I went to the shop ___ buy some bread.", o: ["for", "to", "for to", "so that"], a: 1, x: "to + infinitive for purpose." },
        { t: "mc", s: "She saved money ___ she could travel.", o: ["to", "in order to", "so that", "for"], a: 2, x: "so that + clause." },
        { t: "spot", s: "I'm learning English for get a better job.", wrong: 3, fix: "to", x: "Use to + verb for purpose, not for + verb." },
        { t: "type", s: "We left early so ___ to miss the traffic.", a: ["as"], hint: "One word", x: "so as to = in order to." },
        { t: "kwt", s1: "I wrote it down because I didn't want to forget it.", key: "SO", pre: "I wrote it down", post: "forget it.", a: [["so as"], ["not to"]], x: "so as not to + infinitive." },
        { t: "mc", s: "Take an umbrella ___ it rains.", o: ["in case", "so that", "in order", "despite"], a: 0, x: "in case = because it might happen." },
        { t: "tiles", pre: "He whispered", post: "wake the baby.", tiles: ["so", "as", "not", "to", "for", "don't"], a: ["so", "as", "not", "to"], x: "so as not to + infinitive." },
        { t: "kwt", s1: "She took a taxi because she wanted to arrive on time.", key: "ORDER", pre: "She took a taxi", post: "on time.", a: [["in order"], ["to arrive"]], x: "in order to + verb." }
      ] }
    ] }
