  const unitLocked = (u, ui) => ui >= 3 && !LZ.isPlus() && !(LZ.isLite && LZ.isLite()) && !(st().unlockedUnits || {})[u.id]
    && !u.lessons.some((l) => progress()[l.id]);
  const UNLOCK_PRICE = 50;   // gems for a unit after the first three (the iPhone path asks the same: unlockUnit below)
