    if (LZ.nativeLessons.paid(unit)) { setTimeout(() => { toast("Unlock this unit first", "lock"); go("/uoe"); }); return h("div", {}); }
    const ui = pathOf(u.lessons[0].id).indexOf(u);
    const s = (st().sessions[taskKey(unit)] = st().sessions[taskKey(unit)] || { answers: {} }), spec = taskSpec(unit, t);
