      if (it.t === "tiles") return { ok: norm(value) === norm(it.a.join(" ")) };
      const multi = it.a.some((a) => /\s/.test(a));
      return { ok: it.a.some((a) => (multi ? norm(a) === norm(value) : normWord(a) === normWord(value))) };
