  function extracts(part, start) {
    const pid = (p, i) => p._tid + (part === 1 ? "" : "-p" + part) + "-e" + (i + 1);
    return {
      inline: true, flow: true,
      nums: (p) => range(start, p.extracts.length),
      /* the situation, the recording and the question; the answers follow in the page (flow) */
      content: (p, ctx) => {
        const q = ctx.q, i = q - start, e = p.extracts[i];
        return h("div", { class: "extract lx " + ctx.state(q), "data-q": q },
          h("p", { class: "lx-step" }, h("span", {}, xl(i)), h("span", { class: "lx-of" }, (i + 1) + " / " + p.extracts.length)),
          h("p", { class: "lx-ctx" }, e.ctx),
          player({ id: pid(p, i), clips: p._clips("p" + part + "-e" + (i + 1)), label: xl(i), session: ctx.session, max: p._max }),
          h("p", { class: "lx-q" }, e.q));
      },
      tray: (p, ctx, q) => { const e = p.extracts[q - start]; return h("div", { class: "extract lx-a" }, LZ.choicesUI(ctx, q, e.o), ctx.itemFor(q) ? transcript(e.script) : null); },
      track: (p, q) => pid(p, q - start),
      key: (p, ctx, e) => LZ.keyPick(ctx, e, 3),
      grade: (p, ans) => LZ.total(p.extracts.map((e, i) => { const q = start + i, v = ans[q], k = L(e.a); return { q, got: v === k ? 1 : 0, max: 1, keyLetter: k, key: k + " – " + e.o[e.a], given: pick(e.o, v), x: e.x }; }))
    };
  }
  /* a conversation with two questions (C1 Part 1) – one conversation on screen at a time */
  function extracts2(part, start) {
    const flat = (p) => p.extracts.reduce((a, e, i) => a.concat(e.qs.map((qq) => ({ e, i, qq }))), []);
    return {
      inline: true, flow: true,
      nums: (p) => range(start, flat(p).length),
      content: (p, ctx) => {
        const { e, i, qq } = flat(p)[ctx.q - start];
        const first = start + flat(p).findIndex((x) => x.i === i), k = ctx.q - first;
        return h("div", { class: "extract lx " + ctx.state(ctx.q), "data-q": ctx.q },
          h("p", { class: "lx-step" }, h("span", {}, xl(i)), h("span", { class: "lx-of" }, LZ.tr("Question {0} of {1}", k + 1, e.qs.length))),
          h("p", { class: "lx-ctx" }, e.ctx),
          player({ id: p._tid + "-e" + (i + 1), clips: p._clips("p" + part + "-e" + (i + 1)), label: xl(i), session: ctx.session, max: p._max }),
          h("p", { class: "lx-q" }, qq.q));
      },
      tray: (p, ctx, q) => { const { e, i, qq } = flat(p)[q - start], last = start + flat(p).findIndex((x) => x.i === i) + e.qs.length - 1;
        return h("div", { class: "extract lx-a" }, LZ.choicesUI(ctx, q, qq.o), ctx.itemFor(q) && q === last ? transcript(e.script) : null); },
      track: (p, q) => p._tid + "-e" + (flat(p)[q - start].i + 1),
      key: (p, ctx, e) => LZ.keyPick(ctx, e, 3),
      grade: (p, ans) => LZ.total(flat(p).map(({ qq }, k) => { const q = start + k, v = ans[q], key = L(qq.a); return { q, got: v === key ? 1 : 0, max: 1, keyLetter: key, key: key + " – " + qq.o[qq.a], given: pick(qq.o, v), x: qq.x }; }))
    };
  }
  /* sentence or note completion from one talk (B2 Part 2, B1 Part 3, C1 Part 2) */
  function gaps(part, start) {
    return {
      nums: (p) => range(start, p.items.length),
      content: (p, ctx) => h("div", { class: "stack" },
        player({ id: p._tid + "-p" + part, clips: p._clips("p" + part), label: "Part " + part + " · the talk", session: ctx.session, max: p._max }),
        h("article", { class: "passage" }, p.title ? h("h2", {}, p.title) : null, p.items.map((it, i) => {
          const q = start + i;
          return h("p", {}, LZ.withGaps(it.s.replace("{g}", "{" + q + "}"), () => LZ.gapChip(ctx, q, (ctx.answer(q) || "").toUpperCase())));
        })),
        ctx.checked ? transcript(p.script) : null),
      tray(p, ctx, q) {
        const it = p.items[q - start];
        return h("div", { class: "stack" },
          h("div", { style: "font:400 17px/1.7 var(--read)" }, LZ.withGaps(it.s.replace("{g}", "{x}"), () => h("span", { class: "gap current" }, h("span", { class: "n" }, q), h("span", { class: "gv" }, (ctx.answer(q) || "……").toUpperCase())))),
          h("input", { class: "typein " + ctx.state(q), value: ctx.answer(q) || "", disabled: ctx.locked(q), autocomplete: "off", spellcheck: "false", "aria-label": "Answer " + q, placeholder: "Word or short phrase",
            oninput: (e) => ctx.set(q, e.target.value, { silent: true }) }),
          h("span", { class: "hint" }, p.title ? "One or two words, a number, a date or a time. Spelling counts." : "Write exactly what you hear. Spelling counts."));
      },
      sync(p, ctx, q, root) { const g = root.querySelector('.gap[data-q="' + q + '"] .gv'); if (g) g.textContent = (ctx.answer(q) || "……").toUpperCase(); },
      grade: (p, ans) => LZ.total(p.items.map((it, i) => { const q = start + i, v = ans[q] || ""; const ok = it.a.some((a) => norm(a) === norm(v)); return { q, got: ok ? 1 : 0, max: 1, key: it.a.join(" / ").toUpperCase(), given: v.toUpperCase(), x: it.x }; }))
    };
  }
  /* five speakers, one list of options (B2 Part 3) */
  function match(part, start) {
    return {
      nums: (p) => range(start, p.speakers.length),
      content: (p, ctx) => h("div", { class: "stack" },
        player({ id: p._tid + "-p" + part, clips: p.speakers.flatMap((s, i) => p._clips("p" + part + "-s" + (i + 1))), label: "All five speakers", session: ctx.session, max: p._max }),
        h("div", { class: "card" }, h("p", { class: "eyebrow" }, "Options"), h("div", { class: "stack", style: "gap:8px" }, p.options.map((o, i) => h("div", { class: "row", style: "flex-wrap:nowrap" }, h("span", { class: "pill pink" }, L(i)), h("span", {}, o))))),
        LZ.qList(ctx, range(start, p.speakers.length), p.speakers.map((s, i) => "Speaker " + (i + 1))),
        ctx.checked ? p.speakers.map((sp, i) => transcript(sp.script, "Transcript · Speaker " + (i + 1))) : null),
      tray(p, ctx, q) {
        const i = q - start;
        const usedBy = {}; range(start, p.speakers.length).forEach((n) => { const v = ctx.answer(n); if (v) usedBy[v] = n; });
        return h("div", { class: "stack" },
          !p._max ? player({ id: p._tid + "-s" + (i + 1), clips: p._clips("p" + part + "-s" + (i + 1)), label: "Speaker " + (i + 1) + " only", session: ctx.session, max: 0 }) : bold("Speaker " + (i + 1)),
          LZ.choicesUI(ctx, q, p.options, { two: true, usedBy, onMove: (letter) => { delete ctx.session.answers[usedBy[letter]]; } }));
      },
      key: (p, ctx, e) => LZ.keyPick(ctx, e, 8),
      grade: (p, ans) => LZ.total(p.speakers.map((sp, i) => { const q = start + i, v = ans[q], k = L(sp.a); return { q, got: v === k ? 1 : 0, max: 1, keyLetter: k, key: k + " – " + p.options[sp.a], given: pick(p.options, v), x: sp.x }; }))
    };
  }
  /* five speakers, two tasks answered at the same time (C1 Part 4) */
  function match2(part, start) {
    const n = (p) => p.speakers.length;
    const where = (p, q) => ({ task: q - start < n(p) ? 0 : 1, i: (q - start) % n(p) });
    const taskNums = (p, task) => range(start + task * n(p), n(p));
    return {
      nums: (p) => range(start, n(p) * 2),
      content: (p, ctx) => h("div", { class: "stack" },
        player({ id: p._tid + "-p" + part, clips: p.speakers.flatMap((s, i) => p._clips("p" + part + "-s" + (i + 1))), label: "All five speakers", session: ctx.session, max: p._max }),
        p.tasks.map((task, k) => h("div", { class: "stack", style: "gap:10px" },
          h("div", { class: "card" }, h("p", { class: "eyebrow" }, "Task " + (k + 1)), h("p", { class: "muted small", style: "margin:0 0 10px" }, task.prompt),
            h("div", { class: "stack", style: "gap:8px" }, task.options.map((o, i) => h("div", { class: "row", style: "flex-wrap:nowrap" }, h("span", { class: "pill " + (k ? "blue" : "pink") }, L(i)), h("span", {}, o))))),
          LZ.qList(ctx, taskNums(p, k), p.speakers.map((s, i) => "Speaker " + (i + 1))))),
        ctx.checked ? p.speakers.map((sp, i) => transcript(sp.script, "Transcript · Speaker " + (i + 1))) : null),
      tray(p, ctx, q) {
        const { task, i } = where(p, q);
        const usedBy = {}; taskNums(p, task).forEach((m) => { const v = ctx.answer(m); if (v) usedBy[v] = m; });
        return h("div", { class: "stack" },
          !p._max ? player({ id: p._tid + "-s" + (i + 1), clips: p._clips("p" + part + "-s" + (i + 1)), label: "Speaker " + (i + 1) + " only", session: ctx.session, max: 0 }) : bold("Speaker " + (i + 1)),
          h("p", { class: "muted small", style: "margin:0" }, h("b", {}, "Task " + (task + 1)), " ", h("span", {}, p.tasks[task].prompt.replace(/^For questions [\d–-]+, /, "").replace(/^./, (c) => c.toUpperCase()))),
          LZ.choicesUI(ctx, q, p.tasks[task].options, { two: true, usedBy, onMove: (letter) => { delete ctx.session.answers[usedBy[letter]]; } }));
      },
      key: (p, ctx, e) => LZ.keyPick(ctx, e, 8),
      grade: (p, ans) => LZ.total([0, 1].flatMap((task) => p.speakers.map((sp, i) => {
        const q = start + task * n(p) + i, v = ans[q], k = L(sp.a[task]), opts = p.tasks[task].options;
        return { q, got: v === k ? 1 : 0, max: 1, keyLetter: k, key: k + " – " + opts[sp.a[task]], given: pick(opts, v), x: [].concat(sp.x)[task] || "" };
      })))
    };
  }
  /* one long recording, multiple choice (B2 Part 4, B1 Part 4, C1 Part 3) */
  /* one recording that keeps playing while you answer – shown like Part 1: the player, the question in
     front of you, its answers in the page, one question after another */
  function interview(part, start) {
    return {
      inline: true, flow: true,
      nums: (p) => range(start, p.qs.length),
      content: (p, ctx) => {
        const i = ctx.q - start;
        return h("div", { class: "extract lx " + ctx.state(ctx.q), "data-q": ctx.q },
          h("p", { class: "lx-step" }, h("span", {}, LZ.tr("Question {0} of {1}", i + 1, p.qs.length))),
          player({ id: p._tid + "-p" + part, clips: p._clips("p" + part), label: "Part " + part + " · the interview", session: ctx.session, max: p._max }),
          h("p", { class: "lx-q" }, p.qs[i].q));
      },
      tray: (p, ctx, q) => h("div", { class: "extract lx-a" }, LZ.choicesUI(ctx, q, p.qs[q - start].o),
        ctx.checked && q === start + p.qs.length - 1 ? transcript(p.script) : null),
      key: (p, ctx, e) => LZ.keyPick(ctx, e, p.qs[0].o.length),
      grade: (p, ans) => LZ.total(p.qs.map((qq, i) => { const q = start + i, v = ans[q], k = L(qq.a); return { q, got: v === k ? 1 : 0, max: 1, keyLetter: k, key: k + " – " + qq.o[qq.a], given: pick(qq.o, v), x: qq.x }; }))
    };
  }
  const KINDS = { extracts, extracts2, gaps, match, match2, interview };
  Object.values(LEX).forEach((ex) => { ex.R = {}; ex.parts.forEach((p, i) => { ex.R[i + 1] = KINDS[p.kind](i + 1, p.start); }); });
  const R = LEX.b2.R;
  LZ.listenRenderers = R;
  /* for Smart review and the tests: a test's renderers, whichever exam it belongs to */
  LZ.listenTest = (id) => { const f = findTest(id); return f.t ? { t: f.t, R: f.ex.R, parts: f.ex.parts.length, exam: f.ex.id } : null; };
  LZ.listenExams = LEX;

  const partFor = (t, n, max) => Object.assign({}, t.parts[n], { _tid: t.id, _max: max, _clips: clipsFor(t) });
  const sess = (key) => { const st = LZ.store(); return (st.sessions[key] = st.sessions[key] || { answers: {} }); };
  const answered = (s, ex, t, n) => ex.R[n].nums(t.parts[n]).filter((q) => s.answers[q] != null && s.answers[q] !== "").length;
  const rubric = (ex, n, part) => RUB[ex.id][n](part);

  function nextListening() {
    const st = LZ.store(), ex = LEX[chosen()] || LEX.b2;
    for (const t of practiceList(ex.id)) for (let n = 1; n <= ex.parts.length; n++) {
      if (!lockedTest(t, ex) && !st.results["lprac:" + t.id + ":" + n]) return { href: "#/listening/" + t.id + "/" + n, icon: "head", title: "Part " + n + " – " + ex.parts[n - 1].name, sub: t.title + " · " + ex.parts[n - 1].blurb };
    }
    return null;
  }
  LZ.nextListening = nextListening;

  /* ---------- practice: Listening ---------- */
  route("listening", () => {
    if (window.LZNative && window.LZNative.shell) { setTimeout(() => LZ.go("/drill/listening")); return h("div", {}); }
    const st = LZ.store(), next = nextListening(), ex = LEX[chosen()] || LEX.b2, list = practiceList(ex.id);
    return h("div", { class: "content-narrow u-amber" },
      LZ.pageHead("Listening practice", "Four parts, one recording at a time, with feedback"),
      LZ.exams ? LZ.exams.badge() : null,
      LZ.paperTabs("listening"),
      next ? LZ.hubTop({ next }) : null,
      h("p", { class: "group-title" }, ex.id === "b2" ? "Listening · 4 parts" : ex.name + " · Listening · 4 parts"),
      h("div", { class: "list" }, ex.parts.map((p, i) => { const n = i + 1; return LZ.listRow({ href: list.length === 1 ? "#/listening/" + list[0].id + "/" + n : "#/listening/part/" + n, badge: n, title: p.name, sub: p.blurb + " · " + p.n + " questions",
        end: LZ.dots3(list.filter((t) => st.results["lprac:" + t.id + ":" + n]).length, list.length) }); })));
  }, "listening");

  route("listening/part/:n", ({ n }) => {
    const ex = LEX[chosen()] || LEX.b2, p = ex.parts[n - 1];
    if (!p) return h("div", { class: "empty" }, "That part doesn't exist.");
    const st = LZ.store();
    return h("div", { class: "content-narrow u-amber" },
      LZ.pageHead("Part " + n + " · " + p.name, p.blurb, { href: "#/listening", label: "Practice" }),
      h("div", { class: "list" }, practiceList(ex.id).map((t) => { const r = st.results["lprac:" + t.id + ":" + n], locked = lockedTest(t, ex);
        return LZ.listRow({ href: "#/listening/" + t.id + "/" + n, badge: icon(locked ? "lock" : r ? "check" : "head"), color: r ? "u-green" : "", locked, title: t.practice ? LZ.tr("Practice set {0}", String(t.title).replace(/\D+/g, "")) : t.title, sub: r ? "Best " + r.best + "/" + r.max : "Not started yet" }); })));
  }, "listening");

  route("listening/:id/:part", ({ id, part }) => {
    const { t, ex } = findTest(id), n = +part;
    if (!t || !ex.parts[n - 1]) return h("div", { class: "empty" }, "That exercise doesn't exist.");
    if (lockedTest(t, ex)) return LZ.lockedPage({ title: t.title + " is part of Plus", back: "#/listening" });
    onLeave(stop);
    const count = ex.parts.length, R = ex.R[n], ppart = partFor(t, n, 0);
    /* A short extract has done its job once you check your answer or move to another one; a long talk
       keeps playing while you answer its questions, and stops when the part is done. */
    return lesson({
      renderer: R, part: ppart, session: sess("lp:" + id + ":" + n), mode: "practice", cls: "listen",
      onCheck: () => { if (R.track) stop(); },
      onFocus: (q) => { if (R.track && A.id && A.id !== R.track(ppart, q)) stop(); },
      onDone: () => stop(),
      kicker: (ex.id === "b2" ? "" : ex.name + " · ") + t.title + " · Part " + n, title: ex.parts[n - 1].name, rubric: rubric(ex, n, t.parts[n]), backHref: "/drill/listening", recordKey: "lprac:" + id + ":" + n,
      next: n < count ? { href: "#/listening/" + id + "/" + (n + 1), label: "Part " + (n + 1) } : { href: "#/drill/listening", label: "Finish" }
    });
  }, "listening", { lesson: true });

  function finish(t, ex, s, options = {}) {
    if (s.finished) return;
    stop();
    let raw = 0;
    for (let p = 1; p <= ex.parts.length; p++) raw += ex.R[p].grade(t.parts[p], s.answers).score;
    Object.assign(s, { finished: true, finishedAt: Date.now(), raw, scale: scaleFor(ex, raw) });
    const entry = { kind: "listening", testId: t.id, at: Date.now(), raw, scale: s.scale, detail: raw + "/" + ex.questions };
    if (ex.id !== "b2") entry.exam = ex.id;
    LZ.store().history.push(entry);
    if (options.save !== false) LZ.save(true);
    addXP(raw + 20, "listening test");
    if (options.navigate !== false) go("/listening/" + t.id + "/result");
    return { raw, scale: s.scale };
  }
  LZ.listeningMock = { finish };
  route("listening/:id/exam/:part", ({ id, part }) => {
    const { t, ex } = findTest(id), n = +part;
    if (!t || !ex.parts[n - 1]) return h("div", { class: "empty" }, "That part doesn't exist.");
    if (lockedTest(t, ex)) return LZ.lockedPage({ title: t.title + " is part of Plus", back: "#/tests" });
    onLeave(stop);
    const s = sess("lx:" + id); s.fp = s.fp || {};
    const count = ex.parts.length;
    const ps = { get answers() { return s.answers; }, set answers(v) { s.answers = v; }, get focus() { return s.fp[n]; }, set focus(v) { s.fp[n] = v; }, get plays() { return (s.plays = s.plays || {}); }, set plays(v) { s.plays = v; }, revealed: {} };
    let armed = false;
    const tabs = h("nav", { class: "parttabs" }, ex.parts.map((p, i) => h("a", { href: "#/listening/" + id + "/exam/" + (i + 1), "aria-current": i + 1 === n ? "page" : null }, "Part " + (i + 1), h("small", {}, answered(s, ex, t, i + 1) + "/" + p.n))));
    const R = ex.R[n], xpart = partFor(t, n, s.finished ? 0 : 2);
    return lesson({
      renderer: R, part: xpart, session: ps, mode: s.finished ? "review" : "exam", cls: "listen",
      onFocus: (q) => { if (R.track && A.id && A.id !== R.track(xpart, q)) stop(); },
      kicker: (ex.id === "b2" ? "" : ex.name + " · ") + t.title + " · Part " + n + " of " + count, title: ex.parts[n - 1].name, rubric: rubric(ex, n, t.parts[n]), backHref: s.finished ? "/listening/" + id + "/result" : "/drill/mock", tabs,
      next: n < count ? { href: "#/listening/" + id + "/exam/" + (n + 1), label: "Part " + (n + 1) } : { href: "#/listening/" + id + "/result", label: "Results" },
      examFoot: (ctx, isLast) => isLast && n === count ? [h("button", { class: "btn green lg", type: "button", onclick: () => finish(t, ex, s) }, "Finish test")]
        : [h("button", { class: "btn ghost exam-end", type: "button", onclick: (e) => { if (!armed) { armed = true; e.currentTarget.textContent = "Finish & mark?"; return; } finish(t, ex, s); } }, "Finish test"),
          isLast ? h("a", { class: "btn blue lg", href: "#/listening/" + id + "/exam/" + (n + 1) }, "Part " + (n + 1))
            : h("button", { class: "btn blue lg", type: "button", onclick: ctx.next }, "Next")]
    });
  }, "listening", { lesson: true });

  /* the result card to share (share.js), for the web button and the iPhone (LZ.nativeShare) */
  LZ.resultShare = LZ.resultShare || {};
  LZ.resultShare.listening = (id) => {
    const { t, ex } = findTest(id), s = t && LZ.store().sessions["lx:" + id];
    if (!s || !s.finished || s.scale == null) return null;
    return { kicker: ex.name + " mock test", exam: ex.name, score: s.scale, grade: gradeFor(ex, s.scale), rows: [["Listening", s.scale]],
      footer: t.title + " · " + new Date(s.finishedAt || Date.now()).toLocaleDateString(LZ.dateLocale ? LZ.dateLocale() : "en-GB", { day: "numeric", month: "long", year: "numeric" }) };
  };

  route("listening/:id/result", ({ id }) => {
    const { t, ex } = findTest(id);
    const s = t && LZ.store().sessions["lx:" + id];
    if (!s || !s.finished) return h("div", { class: "empty" }, "You haven't finished this test yet.");
    const g = gradeFor(ex, s.scale), max = ex.questions;
    return h("div", { style: "max-width:760px;margin-inline:auto" },
      h("a", { class: "btn ghost sm", href: "#/drill/mock" }, icon("left"), "Mock tests"),
      h("div", { class: "summary", style: "max-width:none" },
        h("div", { class: "bigring pop", style: "--p:" + (s.raw / max) * 100 + ";--c:var(--" + g.cls + ")" }, h("div", {}, h("b", {}, s.scale), h("small", {}, "scale score"))),
        h("h1", {}, s.raw + " / " + max + " · " + g.label),
        h("div", { class: "card", style: "width:100%;text-align:left" }, barFor(ex, s.scale)),
        LZ.shareButton ? LZ.shareButton(() => LZ.resultShare.listening(id)) : null),
      h("div", { class: "stack" }, ex.parts.map((info, i) => {
        const gr = ex.R[i + 1].grade(t.parts[i + 1], s.answers);
        return h("a", { class: "partrow", href: "#/listening/" + id + "/exam/" + (i + 1) }, h("span", { class: "num" }, i + 1), h("div", {}, h("h3", {}, info.name), h("p", {}, LZ.tr("{0} / {1} · tap to review", gr.score, gr.max))), h("span", { class: "muted" }, icon("right")));
      })),
      h("div", { class: "row", style: "justify-content:center;margin-top:22px" },
        h("button", { class: "btn", type: "button", onclick: () => { delete LZ.store().sessions["lx:" + id]; LZ.save(true); go("/listening/" + id + "/exam/1"); } }, "Retake"),
        h("a", { class: "btn green", href: "#/" }, "Continue learning")));
  }, "listening");

  /* ---------- on the Tests tab: the chosen exam's Listening tests ---------- */
