        s.marks = { [t1.id]: m1, [chosen.id]: m2 }; s.raw = total(m1) + total(m2); s.scale = scaleOf(exam, s.raw); s.note = failed ? sampleError(failed) : "";
        st.history.push(historyEntry({ raw: s.raw, scale: s.scale, detail: "Part 1 " + total(m1) + "/20 · Part 2 " + total(m2) + "/20" }));
