              put(stRow({ icon: "sound", tint: "blue", title: "Offline downloads", noChev: true,
                sub: done ? LZ.tr("Everything is on this phone · {0} MB", r.mbTotal) : LZ.tr("{0} of {1} MB on this phone", r.mbHave, r.mbTotal),
                end: done ? null : r.running ? h("span", { class: "muted small" }, LZ.tr("Downloading…"))
                  : h("button", { class: "btn sm blue", type: "button", onclick: () => LZ.native.call("mediaDownload").then(poll) }, "Download") }));
              if (r.running && !timer) poll();
