        r = await LZ.ai.json("A Cambridge " + level + " English learner got this exercise wrong.\n" + (o.task ? "Instruction: " + o.task + "\n" : "") +
          "Exercise: " + o.sentence + "\n" + ((o.options || []).length ? "Options: " + o.options.join(" / ") + "\n" : "") +
          "Correct answer: " + o.correct + "\nLearner's answer: " + (o.given || "(none)") + "\n" +
          "Reply with JSON only: {\"why\": \"2-3 short sentences" + (lang === "English" ? "" : " in " + lang) + ": why their answer doesn't fit and the correct one does\", \"example\": \"one more English example sentence using the correct answer\", \"tip\": \"one short memory tip" + (lang === "English" ? "" : " in " + lang) + "\"}");
