      rows.push(h("div", { class: "gl-row" }, LZ.obj(obj, 30), h("div", {}, h("b", {}, label), h("small", {}, new Date(x.t).toLocaleTimeString(loc, { hour: "2-digit", minute: "2-digit" }))),
        h("span", { class: "gl-n " + (x.n > 0 ? "in" : "out") }, (x.n > 0 ? "+" : "−") + Math.abs(x.n))));
