  const spend = (cost, why, then) => { if (!LZ.spendGems(cost, why)) return "gems"; then(); LZ.save(true); window.dispatchEvent(new Event("lz-gems")); return "ok"; };
  /* one XP boost at a time: how many times the XP, for how many minutes (core.js addXP reads boostMult) */
