      s.guesses.push(g); LZ.save(true);
      if (g === word) { s.status = "won"; const gems = 10 + (TRIES - s.guesses.length) * 2; s.reward = gems; LZ.addGems(gems, "word"); LZ.addXP(15, "word of the day"); LZ.onGame && LZ.onGame("word"); LZ.save(true); }
      else if (s.guesses.length >= TRIES) { s.status = "lost"; LZ.save(true); }
