    c.fillStyle = gold; roundRect(c, px, 1000, pw, 110, 55); c.fill();
    c.fillStyle = "#3A2600"; c.textBaseline = "middle"; fitText(c, pill, W / 2, 1057, pw - 60, "800 {s} " + DISPLAY, 56);

