        fitText(c, T(label), 140, y + 44, W - 440, "700 {s} " + UI, 42);
        c.textAlign = "right"; c.font = "800 56px " + DISPLAY; c.fillText(String(val), W - 140, y + 50);
        const bw = W - 280, fillW = bw * Math.max(0.04, Math.min(1, (val - 122) / 68));
