    if (document.caretRangeFromPoint) r = document.caretRangeFromPoint(x, y);
    else if (document.caretPositionFromPoint) { const p = document.caretPositionFromPoint(x, y); if (p) { r = document.createRange(); r.setStart(p.offsetNode, p.offset); } }
    if (!r || !r.startContainer || r.startContainer.nodeType !== 3) return null;
    const node = r.startContainer, t = node.textContent, isW = (c) => /[A-Za-z'’-]/.test(c || "");
    let a = r.startOffset, b = a;
