    const left = Math.max(10, Math.min(innerWidth - w - 10, r.left + r.width / 2 - w / 2));
    const above = r.top - ht - 10 > 60;
    pop.style.left = left + "px";
    pop.style.top = (above ? r.top - ht - 10 : r.bottom + 10) + "px";
    pop.classList.add(above ? "up" : "down");
    pop.style.setProperty("--ax", Math.max(18, Math.min(w - 18, r.left + r.width / 2 - left)) + "px");
