    const b = (LZ.weekBanner && LZ.weekBanner()) || (LZ.guidesFor && !Object.keys(LZ.store().guidesSeen || {}).length && LZ.guidesFor("writing").length
      ? { title: LZ.tr("New: exam guides"), sub: LZ.tr("How to write each task, how to ace every Speaking part. In a few cards."), href: LZ.guidesFor("writing")[0].href, icon: "book" } : null);
