    /* One screen, nothing to scroll: the gem, the next lesson, today's quests and a few quick games. Everything else is a tap away in Learn. */
    const pill = (art, value, label, fillPct) => h("div", { class: "gh-pill" }, art, h("div", {}, h("b", {}, value), h("small", {}, label)),
      fillPct != null ? h("span", { class: "gh-meter", "aria-hidden": "true" }, h("i", { style: "width:" + Math.min(100, fillPct) + "%" })) : null);
